DO $$
DECLARE
    v_client_id UUID;
    v_state VARCHAR(30);
    v_message TEXT;
    v_ai_message TEXT;
    v_ai_message_replaced TEXT;
    v_client_name TEXT;
    v_count INTEGER;
    v_delete_count INTEGER;
    v_category TEXT;
    v_action TEXT;
    v_specialty_id INTEGER;
BEGIN
    v_client_id := '{{ $json.user_id }}'::uuid;

    v_message :=
        '{{ ($json.message || "").replace(/'/g, "''") }}';

    v_ai_message :=
        '{{ ($json.ai_message || "").replace(/'/g, "''") }}';

    v_action :=
        '{{ ($json.action || "").replace(/'/g, "''") }}';

    v_category :=
        '{{ ($json.category || "").replace(/'/g, "''") }}';

    SELECT
        c.state,
        c.name
    INTO
        v_state,
        v_client_name
    FROM client c
    WHERE c.id = v_client_id;

    IF POSITION('[NAME]' IN v_ai_message) > 0 THEN
        v_ai_message_replaced :=
            REPLACE(
                v_ai_message,
                '[NAME]',
                COALESCE(
                    NULLIF(TRIM(v_client_name), ''),
                    'Usuario'
                )
            );
    ELSE
        v_ai_message_replaced := v_ai_message;
    END IF;

    IF v_action = 'MATCH_SUCCESS' THEN
        SELECT id
        INTO v_specialty_id
        FROM specialty
        WHERE LOWER(TRIM(specialty)) =
              LOWER(TRIM(v_category))
          AND deleted = FALSE
        LIMIT 1;
    ELSE
        v_specialty_id := NULL;
    END IF;

    IF v_state = 'NORMAL'
       AND v_action IN ('QUESTIONNAIRE', 'MATCH_SUCCESS')
    THEN
        SELECT COUNT(*)
        INTO v_count
        FROM client_chat_context
        WHERE client_id = v_client_id;

        v_delete_count :=
            GREATEST(0, v_count + 2 - 10);

        IF v_delete_count > 0 THEN
            DELETE FROM client_chat_context
            WHERE id IN (
                SELECT id
                FROM client_chat_context
                WHERE client_id = v_client_id
                ORDER BY created_at ASC, id ASC
                LIMIT v_delete_count
            );
        END IF;

        INSERT INTO client_chat_context (
            client_id,
            role,
            message
        )
        VALUES (
            v_client_id,
            'user',
            v_message
        );

        INSERT INTO client_chat_context (
            client_id,
            role,
            message
        )
        VALUES (
            v_client_id,
            'assistant',
            v_ai_message
        );

        INSERT INTO inquiry (
            client_id,
            question,
            answer,
            specialty_id
        )
        VALUES (
            v_client_id,
            v_message,
            v_ai_message_replaced,
            v_specialty_id
        );
    END IF;
END $$;

SELECT
    '{{ ($json.message || "").replace(/'/g, "''") }}' AS message,
    '{{ ($json.action || "").replace(/'/g, "''") }}' AS action,
    '{{ $json.user_id }}' AS user_id,
    '{{ ($json.ai_message || "").replace(/'/g, "''") }}' AS ai_message,
    CASE
        WHEN POSITION(
            '[NAME]'
            IN '{{ ($json.ai_message || "").replace(/'/g, "''") }}'
        ) > 0
        THEN REPLACE(
            '{{ ($json.ai_message || "").replace(/'/g, "''") }}',
            '[NAME]',
            COALESCE(
                (
                    SELECT NULLIF(TRIM(c.name), '')
                    FROM client c
                    WHERE c.id = '{{ $json.user_id }}'::uuid
                ),
                'Usuario'
            )
        )
        ELSE '{{ ($json.ai_message || "").replace(/'/g, "''") }}'
    END AS answer,
    '{{ ($json.category || "").replace(/'/g, "''") }}' AS category,
    CASE
        WHEN '{{ ($json.action || "").replace(/'/g, "''") }}' = 'MATCH_SUCCESS'
        THEN (
            SELECT id
            FROM specialty
            WHERE LOWER(TRIM(specialty)) =
                  LOWER(TRIM('{{ ($json.category || "").replace(/'/g, "''") }}'))
              AND deleted = FALSE
            LIMIT 1
        )
        ELSE NULL
    END AS specialty_id,
    COALESCE(
        (
            SELECT NULLIF(TRIM(c.name), '')
            FROM client c
            WHERE c.id = '{{ $json.user_id }}'::uuid
        ),
        'Usuario'
    ) AS client_name;

