const clientData = $("Code in JavaScript6").first().json;
const aiData = $("AI Agent").first().json;

const aiOutput = String(aiData.output ?? "").trim();

const action =
    aiOutput.match(/\[ACTION=([A-Z_]+)\]/)?.[1]?.trim() || "";

const category =
    aiOutput.match(/\[CATEGORY=([^\]]+)\]/)?.[1]?.trim() || "";

const aiMessage = aiOutput
    .replace(/\[ACTION=[A-Z_]+\]/g, "")
    .replace(/\[CATEGORY=[^\]]+\]/g, "")
    .replace(/\[P[1-4]\]/g, "")
    .trim();

return [
    {
        json: {
            message: String(clientData.message ?? "").trim(),
            user_id: String(clientData.user_id ?? "").trim(),

            ai_output: aiOutput,
            ai_message: aiMessage,

            action,
            category
        }
    }
];

const raw = $json;

const headers = raw.headers || {};
const body = raw.body || {};

const message =
    String(body.message || '').trim();

const userId =
    String(body.userId || '').trim();

const action =
    String(body.action || '').trim();

const host =
    String(headers.host || '').trim();

const hostIp =
    host.split(':')[0].trim();

const ip =
    hostIp && userId
        ? `${hostIp}_USER_${userId}`
        : hostIp || userId || '';

const nameMatch =
    action.match(/\[NAME=([^\]]+)\]/);

const name =
    nameMatch
        ? nameMatch[1].trim()
        : '';

const cleanAction =
    nameMatch
        ? ''
        : action;

return [
    {
        json: {
            user_id: userId,
            message,
            action: cleanAction,
            name,
            ip
        }
    }
];

