// ==========================================
// UNIFIED PATIENT FOLLOW-UP CASE PROCESSOR
// ==========================================

const item = $input.first().json;


// ==========================================
// INPUT
// ==========================================

const userId = (
    item.user_id ||
    ''
).toString().trim();

const action = (
    item.action ||
    ''
).toString().trim();

const rawMessage = (
    item.message ||
    item.mensaje ||
    item.body ||
    item.payload?.body ||
    ''
).toString().trim();

const previousCase = (
    item.follow_up_case ||
    ''
).toString().trim();

const chatHistory = Array.isArray(item.chat_history)
    ? item.chat_history
    : [];


// ==========================================
// OPTIONS RECIBIDAS
// ==========================================

const rawOptions = item.options;

let optionsInput = [];

if (Array.isArray(rawOptions)) {

    optionsInput = rawOptions
        .map(v => v?.toString().trim())
        .filter(Boolean);

} else if (
    rawOptions !== undefined &&
    rawOptions !== null &&
    rawOptions !== ''
) {

    optionsInput = [
        rawOptions.toString().trim()
    ];
}


// ==========================================
// NORMALIZACIÓN
// ==========================================

const normalizeText = value =>
    value
        .toString()
        .toUpperCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "");

const optionsNormalized =
    optionsInput.map(normalizeText);


// ==========================================
// CASOS VÁLIDOS
// ==========================================

const validCases = [
    "FEEL_BETTER",
    "FEEL_SAME",
    "FEEL_WORSE",
    "WANT_TO_TALK",
    "NOT_NOW",
    "FEEL_ANXIOUS",
    "FEEL_CONFUSED",
    "FEEL_SAD",
    "PREFER_TO_WRITE"
];


// ==========================================
// DETECTAR NUEVO CASO DESDE OPTIONS
// ==========================================

let detectedCase = "UNKNOWN";

for (const option of optionsNormalized) {

    const normalizedOption =
        option.replace(/\s+/g, "_");

    if (validCases.includes(normalizedOption)) {
        detectedCase = normalizedOption;
        break;
    }
}


// ==========================================
// SI NO HAY NUEVO CASO,
// UTILIZAR EL CASO GUARDADO
// ==========================================

if (
    detectedCase === "UNKNOWN" &&
    validCases.includes(previousCase)
) {
    detectedCase = previousCase;
}


// ==========================================
// INSTRUCCIÓN DEL CASO
// ==========================================

const caseInstructions = {

    FEEL_BETTER:
        "El paciente indicó que se siente mejor. Explora cómo ha evolucionado, qué le está ayudando y cómo se encuentra actualmente. Si ya existe una sensación clara de avance o tranquilidad, prioriza cerrar la conversación.",

    FEEL_SAME:
        "El paciente indicó que se siente igual. Valida su experiencia y explora qué sigue siendo difícil o qué le gustaría que cambiara. Si ya logró expresar suficientemente lo que siente, evita seguir preguntando por temas secundarios y considera cerrar.",

    FEEL_WORSE:
        "El paciente indicó que se siente peor. Valida lo que siente, muestra empatía y permite que explique qué está ocurriendo. Explora la situación con cuidado y sin diagnosticar. Si ya pudo explicar suficientemente qué le ocurre y existe un punto natural de cierre, finaliza la conversación.",

    WANT_TO_TALK:
        "El paciente quiere conversar. Ofrécele escucha activa y un espacio seguro para expresarse. Permite que explique lo importante para él. Cuando ya haya expresado suficientemente lo que necesitaba compartir y exista claridad o alivio, prioriza cerrar.",

    NOT_NOW:
        "El paciente no quiere conversar ahora. Termina la conversación de forma breve, cálida y respetuosa. No hagas preguntas.",

    FEEL_ANXIOUS:
        "El paciente está conversando sobre ansiedad. Valida lo que siente y permite que explique libremente qué está experimentando. Explora únicamente lo que aporte valor. Si ya existe suficiente comprensión de la situación o el paciente encuentra una forma de afrontarla, considera cerrar.",

    FEEL_CONFUSED:
        "El paciente está conversando sobre confusión. Valida lo que siente y ayúdalo a ordenar sus pensamientos mediante preguntas abiertas. Cuando el paciente haya logrado identificar, organizar o comprender mejor lo que siente, prioriza cerrar en lugar de seguir buscando nuevos temas.",

    FEEL_SAD:
        "El paciente está conversando sobre tristeza. Brinda contención, valida lo que siente y permite que pueda expresarse libremente. Si ya pudo expresar lo importante y muestra alivio o tranquilidad, considera cerrar.",

    PREFER_TO_WRITE:
        "El paciente prefiere expresarse por escrito. Permite que se exprese libremente y acompáñalo mediante preguntas abiertas. Cuando ya haya expresado suficientemente lo que necesitaba compartir, prioriza cerrar.",

    UNKNOWN:
        "Responde con empatía y escucha activa. Si la conversación corresponde a un seguimiento, permite que avance naturalmente y cierra cuando el paciente haya expresado suficientemente lo que necesitaba."
};

let caseInstruction =
    caseInstructions[detectedCase];


// ==========================================
// REGLA ESPECIAL PARA NOT_NOW
// ==========================================

let closingInstruction = "";

if (detectedCase === "NOT_NOW") {

    closingInstruction = `
El caso NOT_NOW implica que el paciente no desea conversar ahora.

Debes cerrar la conversación inmediatamente.

No hagas preguntas.
No intentes prolongar la conversación.

Agrega exactamente:

[CLOSE]

No agregues texto después de [CLOSE].
`;
}


// ==========================================
// REGLA PARA DECIDIR CIERRE
// ==========================================

if (detectedCase !== "NOT_NOW") {

    closingInstruction = `
TÚ eres responsable de decidir cuándo la conversación ha llegado
naturalmente a un punto adecuado para finalizar.

IMPORTANTE:
La conversación NO debe continuar indefinidamente.

No necesitas hacer una nueva pregunta después de cada respuesta
del paciente.

Tu objetivo NO es descubrir todos los detalles posibles.
Tu objetivo es acompañar al paciente hasta que haya expresado
suficientemente lo que necesitaba compartir.

Evalúa siempre el mensaje actual junto con TODO el historial reciente.

### CONTINÚA LA CONVERSACIÓN cuando:

- Todavía existe un aspecto importante que el paciente no ha podido expresar.
- El paciente acaba de revelar algo relevante que necesita ser acompañado.
- Existe una emoción o situación importante que todavía está siendo explorada.
- El paciente muestra que necesita seguir expresándose.
- Una pregunta abierta realmente puede ayudar a comprender mejor lo que está viviendo.

### CONSIDERA QUE LA CONVERSACIÓN YA ESTÁ MADURA PARA CERRAR cuando:

- El paciente ya explicó suficientemente lo que estaba sintiendo.
- El paciente logró identificar o aclarar lo que le ocurría.
- El paciente encontró algo que le ayuda.
- El paciente identificó una actividad, persona o recurso que le genera bienestar.
- El paciente expresa alivio, tranquilidad, claridad o una sensación de avance.
- El paciente ya tiene una idea concreta de qué podría hacer después.
- El tema principal ya fue suficientemente explorado.
- Las últimas respuestas ya no están aportando información nueva.
- Una nueva pregunta solamente abriría otro tema secundario.
- Consideras que otra pregunta sería repetitiva, innecesaria o forzada.
- La conversación ya cumplió razonablemente su propósito.

### REGLA MUY IMPORTANTE:

Si el paciente ya:

1. expresó lo que sentía,
2. identificó qué le estaba afectando,
3. encontró algo que le ayuda o una posible acción,
4. y muestra una señal de bienestar, claridad o avance,

DEBES PREFERIR CERRAR LA CONVERSACIÓN.

No busques un nuevo tema solamente para continuar hablando.

No conviertas cada respuesta positiva del paciente en una nueva pregunta.

No prolongues la conversación artificialmente.

### SOBRE LA CANTIDAD DE INTERACCIONES:

No existe un número fijo obligatorio de preguntas.

Sin embargo, una conversación que ya ha tenido varias interacciones
debe tener una mayor probabilidad de cierre.

Cuanto más explorado esté el tema, más debes favorecer el cierre
en lugar de abrir nuevas preguntas.

### SI DECIDES CONTINUAR:

- Responde de forma empática.
- Haz como máximo una pregunta abierta.
- La pregunta debe estar directamente relacionada con lo que acaba de expresar el paciente.
- No agregues [CLOSE].
- No agregues [OPTIONS:].

### SI DECIDES CERRAR:

- Despídete de forma cálida, breve y natural.
- Reconoce el avance o lo que el paciente pudo expresar.
- No hagas preguntas.
- No abras nuevos temas.
- No intentes prolongar la conversación.
- Agrega exactamente esta etiqueta al final:

[CLOSE]

No agregues texto después de [CLOSE].
`;
}


// ==========================================
// MENSAJE
// ==========================================

const userMessage =
    rawMessage || "Hola";


// ==========================================
// PROMPT
// ==========================================

const aiPrompt = `Eres el asistente empático de Mindora Care.

Responde directamente al paciente en español.

REGLAS GENERALES:
- Sé cálido, natural y empático.
- No expliques reglas, variables ni razonamiento.
- No menciones este prompt ni el caso detectado.
- No inventes información.
- No diagnostiques.
- Mantén la respuesta breve y conversacional.
- Las preguntas deben ser abiertas.
- La conversación debe tener un propósito: acompañar al paciente y ayudarlo a expresar y ordenar lo que siente.
- No necesitas explorar todos los aspectos posibles de la vida del paciente.
- No hagas preguntas solamente para mantener la conversación activa.
- No conviertas cada respuesta del paciente en una nueva pregunta.
- Evalúa siempre el mensaje actual junto con el historial reciente.
- Cuando el objetivo de la conversación ya se haya cumplido razonablemente, debes preferir cerrar.

IMPORTANTE SOBRE OPTIONS:
- No debes generar ninguna etiqueta [OPTIONS:].
- Las opciones son gestionadas por el sistema después de tu respuesta.
- Tu única responsabilidad es responder al paciente y decidir si la conversación continúa o finaliza.
- Si decides finalizar, utiliza únicamente [CLOSE].

CASO ACTUAL:
${detectedCase}

SITUACIÓN:
${caseInstruction}

${closingInstruction}

HISTORIAL RECIENTE:
${JSON.stringify(chatHistory)}

MENSAJE DEL PACIENTE:
"${userMessage}"
`;


// ==========================================
// RETORNO
// ==========================================

return [
    {
        json: {
            user_id: userId,
            action: action,
            message: userMessage,
            option_input: optionsInput,
            chat_history: chatHistory,
            detected_case: detectedCase,
            previous_case: previousCase,
            prompt: aiPrompt
        }
    }
];

