const postgresItem =
    $('Execute a SQL query5').first()?.json || {};


// ==========================================
// DATOS DEL HTTP REQUEST2
// ==========================================

const httpRequest2Raw =
    $('HTTP Request2').first()?.json || {};


// ==========================================
// PSICÓLOGOS
// ==========================================

const rawPsychologists =
    httpRequest2Raw?.data?.GetPsychologistByAffinityTest;

const psychologists =
    Array.isArray(rawPsychologists)
        ? rawPsychologists
        : [];


// ==========================================
// DATOS DEL CLIENTE
// ==========================================

const clientName =
    String(
        postgresItem.client_name ||
        "Usuario"
    ).trim();

const userId =
    String(
        postgresItem.user_id ||
        ""
    ).trim();

const specialty =
    String(
        postgresItem.category ||
        "bienestar emocional"
    ).trim();


// ==========================================
// SELECCIONAR PSICÓLOGOS
// ==========================================

const selectedPsychologists =
    psychologists.slice(0, 2);

const hasPsychologists =
    selectedPsychologists.length > 0;


// ==========================================
// CONSTRUIR RESPUESTA FINAL
// ==========================================

let answer = "";

if (hasPsychologists) {

    const psychologistsText =
        selectedPsychologists
            .map(psy => {

                const specialities =
                    Array.isArray(psy.specialities)
                        ? psy.specialities
                            .map(s => String(s?.specialty || "").trim())
                            .filter(Boolean)
                        : [];

                const specialitiesText =
                    specialities.length > 0
                        ? specialities.join(", ")
                        : "No especificadas";

                const reason =
                    `Su experiencia y especialidades están relacionadas con ${specialty}.`;

                return `
userName: ${String(psy.userName || "").trim()}
yearsExperience: ${psy.yearsExperience ?? 0}
averageRating: ${psy.averageRating ?? 0}
photoImageUrl: ${psy.photoImageUrl || "No especificada"}
residenceCountry -> code: ${psy.residenceCountry?.code || "No especificado"}
approach: ${psy.approach?.approach || "No especificado"}
specialities: ${specialitiesText}
reason: ${reason}
`.trim();

            })
            .join("\n\n");


    answer = `
${clientName}, gracias por completar el proceso.

Hemos identificado que la especialidad que mejor se relaciona con lo que nos compartiste es ${specialty}.

init_action: view_psychologists

${psychologistsText}

end_action
`.trim();

} else {

    answer = `
${clientName}, gracias por completar el proceso.

Hemos identificado que la especialidad que mejor se relaciona con lo que nos compartiste es ${specialty}.

Actualmente no hay psicólogos disponibles para asignación en este momento. El equipo de Mindora Care se pondrá en contacto posteriormente.
`.trim();

}


// ==========================================
// OUTPUT
// ==========================================

return [
    {
        json: {
            answer,
            user_id: userId
        }
    }
];

